function rpeMeasurements(ex){
 const key=keyEx(ex),out=[];
 for(const h of filteredStatHistory()){
  let before=0;
  for(const group of exerciseGroups(h.exercises||[])){
   const n=Math.max(0,...group.map(({e})=>(e.setsDone||[]).length));
   for(let j=0;j<n;j++)for(const {e} of group){
    const final=e.category==='finaldrop'||e.relation?.type==='finaldrop';
    if(final&&j!==n-1)continue;
    const st=e.setsDone?.[final?0:j];
    if(!st?.done)continue;
    if(keyEx(e)===key){
     const rpe=setRPE(e,st),kg=effectiveKg(e,st),reps=Number(st.reps);
     if(rpe!==null&&Number.isFinite(kg)&&kg>0&&Number.isFinite(reps)&&reps>0)
      out.push({rpe,kg,reps,before,date:h.date,sessionName:h.dayName||'',programName:h.programName||'',sessionId:h.id,setIndex:final?0:j});
    }
    before++;
   }
  }
 }
 return out;
}
function rpeContradicted(entry,all){
 return all.some(other=>other!==entry&&other.rpe<entry.rpe&&other.kg>=entry.kg&&other.reps>=entry.reps);
}
function rpePick(ex,rpe){
 const all=rpeMeasurements(ex),target=Number(rpe);
 if(!Number.isFinite(target))return null;
 // A lower-RPE observation dominates any equal-or-weaker higher-RPE
 // observation. A historical measurement remains untouched.
 const eligible=all.filter(x=>x.rpe<=target&&!rpeContradicted(x,all));
 if(!eligible.length)return null;
 const exact=eligible.filter(x=>x.rpe===target);
 const strongerLower=eligible.filter(x=>x.rpe<target);
 // A higher-RPE result cannot recommend a load/reps pair below a
 // recorded lower-RPE result in both dimensions.
 const comparable=exact.filter(x=>!strongerLower.some(y=>y.kg>=x.kg&&y.reps>=x.reps));
 const choices=comparable.length?comparable:strongerLower;
 if(!choices.length)return null;
 choices.sort((a,b)=>a.before-b.before||b.kg-a.kg||b.reps-a.reps||String(b.date).localeCompare(String(a.date)));
 const pick=choices[0];
 return {...pick,corrected:pick.rpe!==target,requestedRPE:target};
}
function rpeBest(ex,rpe){return rpePick(ex,rpe)}
function rpeBestLegacy(ex,rpe){const values=historyMatching(ex).filter(eligibleStats).flatMap(h=>h.intensityType==='RPE'&&String(h.intensityValue)===String(rpe)?(h.setsDone||[]).filter(x=>x.done).map(x=>({kg:effectiveKg(h,x),reps:Number(x.reps),type:x.loadType||h.loadType,value:x.loadValue,unit:x.loadUnit||h.loadUnit})):[]).filter(x=>x.kg!==null&&x.kg>0&&x.reps>0);values.sort((a,b)=>b.kg-a.kg||b.reps-a.reps);return values[0]||null}
function rpeHistoryBest(ex,rpe){const values=historyMatching(ex).filter(eligibleStats).flatMap(h=>(h.setsDone||[]).filter(x=>x.done&&setRPE(h,x)===Number(rpe)).map(x=>({kg:effectiveKg(h,x),reps:Number(x.reps),date:h.date}))).filter(x=>Number.isFinite(x.kg)&&x.kg>0);values.sort((a,b)=>b.kg-a.kg||b.date.localeCompare(a.date));return values[0]||null}
