 function rootIndex(i){let k=i,seen=new Set();while(items[k]?.relation?.parentId&&GROUP_TYPES.has(items[k].relation.type)){const parent=byId.get(items[k].relation.parentId);if(parent===undefined||seen.has(parent))break;seen.add(k);k=parent}return k}
