// Stimolo e fatiche si azzerano per sessione; l'ordine è quello degli esercizi e dei set nello storico.
function muscleFatigueIncrement(n,isPrime,fatigue){
 const sequence=isPrime?[.15,.15,.20,.20,.25]:[.05,.07,.07,.08,.08,.10];
 const ceiling=isPrime?1:.5;
 const requested=n<sequence.length?sequence[n]:Math.max(0,ceiling-fatigue);
 return Math.max(0,Math.min(1-fatigue,requested));
}
// La serie n-esima è già conteggiata nel valore di fatica sistemica restituito.
function systemicFatigue(n){
 if(n<3)return 0;
 if(n<=18)return Math.floor(n/3)*.05;
 if(n<=27)return .30+Math.floor((n-18)/3)*.10;
 return Math.min(1,.60+(n-27)*.05);
}
function muscleScores(){
 const totals=new Map();
 // Ordinamento stabile tra sessioni, senza riordinare esercizi o set all'interno di una sessione.
 const history=filteredStatHistory().map((h,i)=>({h,i})).sort((a,b)=>String(a.h.date||'').localeCompare(String(b.h.date||''))||a.i-b.i);
 for(const {h} of history){
  const local=new Map();let completed=0;
  for(const e of h.exercises||[]){
   // Anche i set di esercizi senza muscoli assegnati contribuiscono alla fatica sistemica.
   const muscles=[...new Set(String(e.muscles||'').split(',').map(m=>m.trim()).filter(Boolean).map(m=>m.toLocaleLowerCase('it')))];
   const names=String(e.muscles||'').split(',').map(m=>m.trim()).filter(Boolean);
   for(const set of e.setsDone||[]){
    if(!set.done||['drop','finaldrop'].includes(e.category)||['drop','finaldrop'].includes(e.relation?.type))continue;
    completed++;
    const multiplier=Math.max(.1,1-systemicFatigue(completed));
    muscles.forEach((key,idx)=>{
     const state=local.get(key)||{name:names.find(m=>m.toLocaleLowerCase('it')===key)||key,n:0,stimulus:0,fatigue:0};
     const prime=idx===0;
     state.stimulus+=Math.max(.05,(prime?1:.5)-state.fatigue)*multiplier;
     state.fatigue+=muscleFatigueIncrement(state.n,prime,state.fatigue);
     state.n++;
     local.set(key,state);
    });
   }
  }
  for(const [key,v] of local){const prev=totals.get(key);totals.set(key,{name:prev?.name||v.name,score:(prev?.score||0)+v.stimulus,sets:(prev?.sets||0)+v.n})}
 }
 return [...totals.values()].sort((a,b)=>b.score-a.score||a.name.localeCompare(b.name,'it'));
}
function muscleExampleCurve(kind){
 let s=0,f=0;const values=[0];
 for(let i=1;i<=35;i++){
  s+=Math.max(.05,1-f)*Math.max(.1,1-systemicFatigue(i));
  f+=muscleFatigueIncrement(i-1,true,f);
  values.push(kind==='stimulus'?s:kind==='local'?f:systemicFatigue(i));
 }
 const W=310,L=39,R=299,T=15,B=120,maxY=kind==='stimulus'?Math.ceil(Math.max(...values)*2)/2:1;
 const sx=i=>L+i*(R-L)/35,sy=v=>B-v/maxY*(B-T);
 const color=kind==='stimulus'?'#4285f4':'#e24b4b';
 const grid=Array.from({length:5},(_,i)=>{const v=maxY*i/4,y=sy(v);const label=kind!=='stimulus'&&i===4?'MAX':v.toFixed(2).replace(/\.?0+$/,'');return `<line x1="${L}" y1="${y}" x2="${R}" y2="${y}" stroke="#42454c" stroke-width=".65"/><text x="${L-5}" y="${y+3}" fill="#bbb" font-size="9" text-anchor="end">${label}</text>`}).join('');
 const pts=values.map((v,i)=>`${sx(i)},${sy(v)}`).join(' ');
 const ticks=[3,6,10,15,20,25].map(i=>`<text x="${sx(i)}" y="136" text-anchor="middle" fill="#aaa" font-size="9">${i}</text>`).join('');
 const label=kind==='stimulus'?'Stimolo':kind==='local'?'Fatica locale':'Fatica sistemica';
 return `<svg class="muscle-example-chart" viewBox="0 0 ${W} 146" role="img" aria-label="Prime Mover: ${label}"><path d="M${L} ${T} V${B} H${R}" stroke="#777" stroke-width=".8" fill="none"/>${grid}<polyline points="${pts}" fill="none" stroke="${color}" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>${ticks}</svg>`;
}
function muscleHelp(){
 const table=[[1,'0,15','0,05'],[2,'0,15','0,07'],[3,'0,20','0,07'],[4,'0,20','0,08'],[5,'0,25','0,08'],[6,'fino a 1','0,10'],['7+','fino a 1','fino a 0,5']];
 const systemic=[['Serie','1–2','3','6','9','12','15','18','21','24','27','28–35+'],['F. sistemica','0','0,05','0,10','0,15','0,20','0,25','0,30','0,40','0,50','0,60','+0,05/serie → 1']];
 return `<div class="muscle-help"><p class="hint">I punteggi indicano quali muscoli sono stati maggiormente privilegiati dagli allenamenti registrati e dove si è concentrato il lavoro. Sono stime orientative, non misure dello stimolo ipertrofico effettivo.</p><details><summary>Formule</summary><div class="muscle-formula">ΔS locale = max(0,05; B − F locale precedente)<br>ΔS = ΔS locale × max(0,1; 1 − F sistemica)<br>S nuova = S precedente + ΔS<br>F locale nuova = min(1; F locale precedente + ΔF)<br>B = 1 (Prime) o 0,5 (Second)</div><p class="hint">Fatica sistemica aggiornata sul set corrente; fatica locale precedente per lo Stimolo. Tutte le variabili ripartono da zero a ogni allenamento.</p></details><details><summary>Incrementi della fatica</summary><table><thead><tr><th>Set muscolo</th><th>Prime</th><th>Second</th></tr></thead><tbody>${table.map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td><td>${r[2]}</td></tr>`).join('')}</tbody></table><p class="hint">La fatica locale non supera 1; «fino a» aggiunge solo la quota mancante.</p><div style="overflow-x:auto"><table style="min-width:560px"><tbody>${systemic.map(row=>`<tr>${row.map((v,i)=>i===0?`<th>${v}</th>`:`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="hint">Dalla 28ª serie +0,05 a ogni serie fino a MAX (1); il moltiplicatore è almeno 0,1, anche a fatica MAX.</p></details><details><summary>Curve illustrative</summary><h4>Prime Mover</h4><div class="muscle-chart-pair">${[['stimulus','Stimolo totale · blu'],['local','Fatica locale · rosso'],['systemic','Fatica sistemica · rosso']].map(([kind,label])=>`<div><small>${label}</small>${muscleExampleCurve(kind)}</div>`).join('')}</div></details></div>`;
}


