function chartYTicks(lo,hi){const steps=[.5,1,2,2.5,5,10,20,25,50,100,200,500,1000];const step=steps.find(v=>(hi-lo)/v<=6)||Math.ceil((hi-lo)/5000)*5000;const ticks=[];for(let v=Math.ceil(lo/step)*step;v<=hi+step*.001;v+=step)ticks.push(Math.round(v*2)/2);return ticks}
