 const trendLine=trend?`<line x1="${L}" y1="${sy(trend.a+trend.b*start)}" x2="${R}" y2="${sy(trend.a+trend.b*end)}" stroke="#783012" stroke-dasharray="7 5" opacity=".83" stroke-width="2"/>`:'';
