function regression(pts){if(pts.length<2)return null;const t0=pts[0].x,scale=86400000;const xs=pts.map(p=>(p.x-t0)/scale),mx=xs.reduce((a,b)=>a+b,0)/xs.length,my=pts.reduce((a,p)=>a+p.y,0)/pts.length;let numerator=0,denominator=0;pts.forEach((p,i)=>{numerator+=(xs[i]-mx)*(p.y-my);denominator+=(xs[i]-mx)**2});if(denominator===0)return null;const b=numerator/denominator/scale;return {a:my-b*(t0+mx*scale),b}}
