function showBodyHistory(){modal({title:'Valori Corporei',body:`${bodyCharts()}${bodyEntries().map(x=>`<div class="card"><div class="row"><div><strong>${x.type.toUpperCase()}</strong> · ${sessionTime(x.date)}<div class="sub">${x.value} ${x.unit} · ${Number(bodyValue(x)||0).toFixed(2)} kg</div></div><button class="btn secondary small" data-action="editBody" data-id="${x.id}">Modifica</button>${trash('deleteBody',`data-id="${x.id}"`)}</div></div>`).join('')||'<p>Nessuna misurazione.</p>'}`})}
function prTimeline(key){let best=null;const events=[];for(const h of data.history.slice().sort((a,b)=>a.date.localeCompare(b.date))){for(const e of h.exercises){if(!eligibleStats(e)||keyEx(e)!==key)continue;for(const s of e.setsDone||[]){const kg=effectiveKg(e,s),reps=clusterStatsReps(e,s);if(!s.done||!Number.isFinite(kg)||kg<=0||!Number.isFinite(reps)||reps<1)continue;if(!best||kg>best.kg||(kg===best.kg&&reps>best.reps)){best={kg,reps};events.push({id:h.id+':'+e.id+':'+events.length,date:h.date,kg,reps,key,value:kg*reps})}}}}return events}
