function pwrTimeline(key){const rms=oneRMTimeline(key),bws=bodyEntries().filter(x=>x.type==='bw');const times=[...new Set([...rms.map(x=>x.date),...bws.map(x=>x.date)])].sort();return times.map(date=>{const rm=rms.filter(x=>x.date<=date).at(-1)?.value,bw=latestBW(date);return rm&&bw?{id:uid(),date,rm,bw,value:(rm+(unitForKey(key)==='bwplus'?bw:0))/bw}:null}).filter(Boolean)}

